import React from 'react';
import Svg, {Circle, Path, Polyline} from 'react-native-svg';

type Props = {size: number; color: string};

// Lucide icons. Figma keeps a 2px stroke at every icon size, so the stroke
// is scaled against the 24px grid instead of shrinking with the icon.
function Lucide({size, color, children}: Props & {children: React.ReactNode}) {
  return (
    <Svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={48 / size}
      strokeLinecap="round">
      {children}
    </Svg>
  );
}

