// Outline icons drawn at their design size, exported from Figma.
type OutlineProps = {width: number; height?: number; color: string; d: string};

function Outline({width, height = width, color, d}: OutlineProps) {
  return (
    <Svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} fill="none">
      <Path d={d} stroke={color} strokeWidth={2} strokeLinecap="round" />
    </Svg>
  );
}

