// Material Symbols (filled), exported from Figma at their design size.
function Material({width, height, color, d}: {width: number; height: number; color: string; d: string}) {
  return (
    <Svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      <Path d={d} fill={color} />
    </Svg>
  );
}

